const handleB = new Dot({ point: ax.c2p(C + 2 * Math.PI / B, D), radius: 0.13, color: YELLOW });
const handleC = new Dot({ point: ax.c2p(C, D), radius: 0.13, color: ORANGE });
const handleD = new Dot({ point: ax.c2p(-5.5, D), radius: 0.13, color: PURPLE });
const labelA = new Text({ text: 'A', fontSize: 23, color: GREEN });
const labelB = new Text({ text: 'B', fontSize: 23, color: YELLOW });
const labelC = new Text({ text: 'C', fontSize: 23, color: ORANGE });
const labelD = new Text({ text: 'D', fontSize: 23, color: PURPLE });

