  const endX = C + 2 * Math.PI / B;
  curve.setFunction(f);
  midline.setStart(ax.c2p(-6, D));
  midline.setEnd(ax.c2p(6, D));
  amplitudeGuide.setStart(ax.c2p(peakX, D));
  amplitudeGuide.setEnd(ax.c2p(peakX, D + A));
  handleA.moveTo(ax.c2p(peakX, D + A));
  handleB.moveTo(ax.c2p(endX, D));
  handleC.moveTo(ax.c2p(C, D));
  handleD.moveTo(ax.c2p(-5.5, D));
  labelA.moveTo(ax.c2p(peakX, D + A)).shift([0, A >= 0 ? 0.26 : -0.26, 0]);
  labelB.moveTo(ax.c2p(endX, D)).shift([0.23, 0.26, 0]);
  labelC.moveTo(ax.c2p(C, D)).shift([-0.23, -0.28, 0]);
