  const rightX = ax.c2p(endX, 0)[0];
  periodLine.setStart([leftX, -2.5, 0]);
  periodLine.setEnd([rightX, -2.5, 0]);
  periodLeft.setStart([leftX, -2.42, 0]);
  periodLeft.setEnd([leftX, -2.58, 0]);
  periodRight.setStart([rightX, -2.42, 0]);
  periodRight.setEnd([rightX, -2.58, 0]);
  const inside = C < 0 ? '(x + ' + Math.abs(C).toFixed(2) + ')' : '(x − ' + C.toFixed(2) + ')';
  const offset = D < 0 ? ' − ' + Math.abs(D).toFixed(2) : ' + ' + D.toFixed(2);
  equation.setText('y = ' + A.toFixed(2) + ' sin[' + B.toFixed(2) + inside + ']' + offset);
